<script setup lang="ts">
import {ref,onMounted} from 'vue';import {api,type SetupStatus} from '@/services/api';
const status=ref<SetupStatus|null>(null),username=ref(''),password=ref(''),currentPassword=ref(''),confirm=ref(''),open=ref(false),busy=ref(false),message=ref(''),error=ref('');
onMounted(async()=>{try{status.value=await api.setup();username.value=status.value.username;}catch(e){error.value=(e as Error).message;}});
async function save(){error.value='';message.value='';if(password.value!==confirm.value){error.value='两次新密码不一致。';return;}busy.value=true;try{await api.account(currentPassword.value,username.value,password.value);password.value='';currentPassword.value='';confirm.value='';message.value='账号已更新，其他管理会话已退出。';open.value=false;}catch(e){error.value=(e as Error).message;}finally{busy.value=false;}}
</script>
<template><view class="server-account"><text class="title">客户端接入</text><text class="muted">在打包器填写此服务地址，模板与源码由打包器组合。</text><text class="service-address" selectable>{{status?.publicOrigin||'读取服务地址中…'}}</text><text v-if="status?.localPreview" class="muted">当前为本机预览，远程手机需使用部署后的 HTTPS 域名。</text><button @click="open=!open">{{open?'收起账号设置':'管理员账号与密码'}} {{open?'⌃':'⌄'}}</button><view v-if="open" class="account-editor"><text>管理员账号</text><input v-model="username"/><text>当前密码</text><input v-model="currentPassword" password :maxlength="-1"/><text>新密码</text><input v-model="password" password :maxlength="-1" placeholder="密码由你自行设置"/><text>确认新密码</text><input v-model="confirm" password :maxlength="-1"/><button :disabled="busy" @click="save">保存账号</button></view><text v-if="message" class="muted">{{message}}</text><text v-if="error" class="failure">{{error}}</text></view></template>
<style scoped>.server-account{padding:18px 0;margin-bottom:24px;border-bottom:1px solid var(--studio-border,#35415a)}.title{display:block;font-size:15px;margin-bottom:10px}.muted{display:block;color:var(--studio-muted,#98a5b5);font-size:11px;line-height:1.9}.service-address{display:block;font-size:12px;overflow-wrap:anywhere;padding:14px 0;color:var(--studio-link,#bba8f9)}button{margin-top:12px;padding:10px;border-radius:8px;font-size:12px;background:var(--studio-input,#1b2735);color:inherit}.account-editor>text{display:block;font-size:11px;margin:16px 0 8px}.account-editor input{height:40px;border:1px solid var(--studio-border,#35415a);border-radius:8px;padding:0 10px;font-size:12px}.failure{display:block;color:#ffb0b0;font-size:12px;margin-top:10px}</style>
